sourceFunctions.take_flight_rules:
playsound minecraft:entity.experience_orb.pickup master @a ~ ~ ~ 10 2 1
scoreboard players add currentRule variables 1
execute if score currentRule variables matches 1 in new_dimensions:sky_dimension unless score players variables matches 5.. run tp @a[scores={minigameplayer=1}] -233 22 -645 180 0
execute if score currentRule variables matches 1 in new_dimensions:sky_dimension unless score players variables matches 5.. run tp @a[scores={minigameplayer=2}] -235 22 -645 180 0
execute if score currentRule variables matches 1 in new_dimensions:sky_dimension unless score players variables matches 5.. run tp @a[scores={minigameplayer=3}] -237 22 -645 180 0
execute if score currentRule variables matches 1 in new_dimensions:sky_dimension unless score players variables matches 5.. run tp @a[scores={minigameplayer=4}] -239 22 -645 180 0
execute if score currentRule variables matches 1.. in new_dimensions:sky_dimension unless score players variables matches 5.. run fill -247 14 -640 -228 26 -640 minecraft:polished_andesite replace minecraft:air
execute if score currentRule variables matches 1 in new_dimensions:sky_dimension if score players variables matches 5.. if score players variables matches 5.. run fill -240 24 -646 -232 21 -644 minecraft:glass hollow
execute if score currentRule variables matches 1 at @a[scores={Player=1},nbt={Dimension:"new_dimensions:sky_dimension"}] run summon minecraft:armor_stand ~ ~ ~ {NoGravity:1b,Silent:1b,Invulnerable:1b,Invisible:1b,Tags:["p1","take_flight"]}
execute if score currentRule variables matches 1 at @a[scores={Player=2},nbt={Dimension:"new_dimensions:sky_dimension"}] run summon minecraft:armor_stand ~ ~ ~ {NoGravity:1b,Silent:1b,Invulnerable:1b,Invisible:1b,Tags:["p2","take_flight"]}
execute if score currentRule variables matches 1 at @a[scores={Player=3},nbt={Dimension:"new_dimensions:sky_dimension"}] run summon minecraft:armor_stand ~ ~ ~ {NoGravity:1b,Silent:1b,Invulnerable:1b,Invisible:1b,Tags:["p3","take_flight"]}
execute if score currentRule variables matches 1 at @a[scores={Player=4},nbt={Dimension:"new_dimensions:sky_dimension"}] run summon minecraft:armor_stand ~ ~ ~ {NoGravity:1b,Silent:1b,Invulnerable:1b,Invisible:1b,Tags:["p4","take_flight"]}
execute if score currentRule variables matches 1 at @a[scores={Player=5},nbt={Dimension:"new_dimensions:sky_dimension"}] run summon minecraft:armor_stand ~ ~ ~ {NoGravity:1b,Silent:1b,Invulnerable:1b,Invisible:1b,Tags:["p5","take_flight"]}
execute if score currentRule variables matches 1 at @a[scores={Player=6},nbt={Dimension:"new_dimensions:sky_dimension"}] run summon minecraft:armor_stand ~ ~ ~ {NoGravity:1b,Silent:1b,Invulnerable:1b,Invisible:1b,Tags:["p6","take_flight"]}
execute if score currentRule variables matches 1 at @a[scores={Player=7},nbt={Dimension:"new_dimensions:sky_dimension"}] run summon minecraft:armor_stand ~ ~ ~ {NoGravity:1b,Silent:1b,Invulnerable:1b,Invisible:1b,Tags:["p7","take_flight"]}
execute if score currentRule variables matches 1 at @a[scores={Player=8},nbt={Dimension:"new_dimensions:sky_dimension"}] run summon minecraft:armor_stand ~ ~ ~ {NoGravity:1b,Silent:1b,Invulnerable:1b,Invisible:1b,Tags:["p8","take_flight"]}
execute if score currentRule variables matches 1 at @a[scores={Player=9},nbt={Dimension:"new_dimensions:sky_dimension"}] run summon minecraft:armor_stand ~ ~ ~ {NoGravity:1b,Silent:1b,Invulnerable:1b,Invisible:1b,Tags:["p9","take_flight"]}
execute if score currentRule variables matches 1 at @a[scores={Player=10},nbt={Dimension:"new_dimensions:sky_dimension"}] run summon minecraft:armor_stand ~ ~ ~ {NoGravity:1b,Silent:1b,Invulnerable:1b,Invisible:1b,Tags:["p10","take_flight"]}
execute if score currentRule variables matches 1 run scoreboard players set playingTakeFlight variables 2
execute if score currentRule variables matches 1 run tellraw @a {fallback:"There is a 1/2 second minimum cooldown between each rocket use.",translate:"mcp.take_flight_rules.1",color:"dark_aqua",type:"translatable"}

execute if score currentRule variables matches 2 run tellraw @a {fallback:"Fly though yellow squares for a speed boost. If you die, you lose momentum and respawn where you are at.",translate:"mcp.take_flight_rules.2",color:"dark_green",type:"translatable"}
execute if score currentRule variables matches 2 run clone -238 34 -645 -230 31 -643 -240 21 -646
execute if score currentRule variables matches 2 run function mcp:give_ready_ups

execute if score currentRule variables matches 3 run tellraw @a {fallback:"The first player to complete three laps wins!",translate:"mcp.take_flight_rules.3",color:"dark_aqua",type:"translatable"}

execute if score currentRule variables matches 1..3 run schedule function mcp:take_flight_rules 3s
execute if score currentRule variables matches 4 run function mcp:ready_up_tellraw

sourceFunctions.take_flight_start:
execute in new_dimensions:sky_dimension run fill -232 24 -644 -240 21 -646 minecraft:air replace minecraft:glass
execute in new_dimensions:sky_dimension run fill -247 14 -640 -228 26 -640 minecraft:air replace minecraft:polished_andesite
scoreboard players set playingTakeFlight variables 3
title @a title {fallback:"Race!",translate:"mcp.race",color:"green",type:"translatable"}
scoreboard players set @a[gamemode=adventure] waypoint 0
scoreboard players set @a[gamemode=adventure] Points 3
scoreboard players set timeLeft variables 2400
effect give @a[gamemode=adventure] minecraft:slow_falling 3 0 true
execute as @a at @s run playsound minecraft:entity.experience_orb.pickup master @s ~ ~ ~ 10 0 1

execute in new_dimensions:sky_dimension run summon marker -257 26 -692 {Tags:["potential_boost","waypoint1","ew"]}
